CREATE MATERIALIZED VIEW mv_daily_revenue AS
SELECT paid_at::date AS day, count(*) AS payments, sum(amount) AS revenue
FROM payment
GROUP BY 1;
CREATE UNIQUE INDEX mv_daily_revenue_day ON mv_daily_revenue (day);
